package test;

import java.util.HashSet;
import java.util.Set;

public class TestClass {
    public char[] processChars(Set<Character> chars) {
        char[] res = new char[chars.size()];
        int i = 0;
        for (Character c : chars) {
            res[i] = c; // Implicit unboxing
            i++;
        }
        return res;
    }

    public char[] otherProcessChars() {
        Set<Character> chars = new HashSet<>();
        chars.add('a');
        chars.add('b');
        return processChars(chars);
    }
}

afterExample:
package test;

import java.util.HashSet;
import java.util.Set;

public class TestClass {
    public char[] processChars(Set<Character> chars) {
        char[] res = new char[chars.size()];
        int i = 0;
        for (Character c : chars) {
            res[i] = c.charValue(); // Explicit unboxing
            i++;
        }
        return res;
    }

    public char[] otherProcessChars() {
        Set<Character> chars = new HashSet<>();
        chars.add('a');
        chars.add('b');
        return processChars(chars);
    }
}

