package test;

import java.util.Set;
import java.util.ArrayList;
import java.util.List;

public class TestClass {
    public void noMatch() {
        // Not a char array
        int[] intArray = new int[5];
        Integer iObj = 10;
        intArray[0] = iObj; // No match (int array, Integer object)

        // Not a Character object
        char[] charArray = new char[5];
        String s = "hello";
        // charArray[0] = s; // This wouldn't compile

        // Already explicit
        char charPrim = 'x';
        Character charObj = Character.valueOf(charPrim);
        charArray[1] = charObj.charValue(); // Already explicit
    }

    public void directAssignment(char[] arr, char c) {
        arr[0] = c; // No match (primitive char to char array, no unboxing needed)
    }
}
